const article =
  $('Validate article length Code node').first().json.article;

const image1 = $('Upload file').first().json;
const image2 = $('Upload file1').first().json;
const image3 = $('Upload file2').first().json;

if (!article) {
  throw new Error('找不到文章內容');
}

if (!image1.id || !image2.id || !image3.id) {
  throw new Error('找不到三張圖片的 Google Drive file ID');
}

const url1 = `https://drive.google.com/uc?export=view&id=${image1.id}`;
const url2 = `https://drive.google.com/uc?export=view&id=${image2.id}`;
const url3 = `https://drive.google.com/uc?export=view&id=${image3.id}`;

let finalArticle = article;

for (const marker of ['[IMAGE_1]', '[IMAGE_2]', '[IMAGE_3]']) {
  const firstIndex = finalArticle.indexOf(marker);

  if (firstIndex === -1) {
    throw new Error(`文章中找不到 ${marker}`);
  }

  const firstPart = finalArticle.slice(0, firstIndex + marker.length);
  const remainingPart = finalArticle
    .slice(firstIndex + marker.length)
    .replaceAll(marker, '');

  finalArticle = firstPart + remainingPart;
}

// 強制每個 marker 獨立成段，確保圖片前後都有換行。
for (const marker of ['[IMAGE_1]', '[IMAGE_2]', '[IMAGE_3]']) {
  finalArticle = finalArticle.replaceAll(
    marker,
    `\n\n${marker}\n\n`
  );
}

// 避免原本已有換行時留下太多空白行。
finalArticle = finalArticle
  .replace(/\n{3,}/g, '\n\n')
  .trim();


return [
  {
    json: {
      article: finalArticle,
      image_url_1: url1,
      image_url_2: url2,
      image_url_3: url3,
      image_file_id_1: image1.id,
      image_file_id_2: image2.id,
      image_file_id_3: image3.id
    }
  }
];

const data = $input.first().json;
const article = data.article ?? '';

if (!article) {
  throw new Error('找不到合併後的文章內容');
}

const chineseCharacterCount = (
  article.match(/[\u4e00-\u9fff]/g) || []
).length;

if (chineseCharacterCount < 1500 || chineseCharacterCount > 1900) {
  throw new Error(
    `文章中文字數不符合要求：目前 ${chineseCharacterCount} 字；目標範圍為 1500–1900 字。`
  );
}

return [
  {
    json: {
      article,
      chineseCharacterCount,
    },
  },
];

const input = $input.first().json;

const text =
  input.output?.[0]?.content?.find(item => item.type === 'output_text')?.text ??
  input.output?.[0]?.content?.[0]?.text ??
  input.output_text ??
  input.text ??
  '';

if (!text) {
  throw new Error('找不到模型輸出文字');
}

const start = text.indexOf('[');
const end = text.lastIndexOf(']');

if (start === -1 || end === -1 || end <= start) {
  throw new Error('找不到 JSON 陣列');
}

const jsonStr = text.slice(start, end + 1);

let imagePrompts;
try {
  imagePrompts = JSON.parse(jsonStr);
} catch (error) {
  throw new Error(`JSON 解析失敗：${error.message}`);
}

if (!Array.isArray(imagePrompts) || imagePrompts.length < 3) {
  throw new Error('圖片 prompt 必須至少 3 個');
}

return [{
  json: {
    image_prompt_1: imagePrompts[0].prompt,
    image_prompt_2: imagePrompts[1].prompt,
    image_prompt_3: imagePrompts[2].prompt,
    image_size_1: imagePrompts[0].size || '1024x1024',
    image_size_2: imagePrompts[1].size || '1024x1024',
    image_size_3: imagePrompts[2].size || '1024x1024',
  }
}];

// n8n Code node
// Node name suggestion: Find marker positions and build image requests
// Place this node immediately after: Get Google Doc structure
// Mode: Run Once for All Items

const googleDoc = $input.first().json;
// 測試尾端節點時設為 true；正式完整 workflow 前改回 false。
const TEST_MODE = false;

const source = TEST_MODE
  ? {
      image_url_1: 'https://drive.google.com/uc?export=view&id=15NIjoUK_jqx36IFI8eDgDorCPEMkTIG3',
      image_url_2: 'https://drive.google.com/uc?export=view&id=1ba5IjZWDVrJQZmkeW2gffTU5olhl5PrY',
      image_url_3: 'https://drive.google.com/uc?export=view&id=1rdUb39zuPVkC4PXuvHgj1Z_ZhJ4rTqPN',
    }
  : $('Code in JavaScript1' ).first().json;


const imageSpecs = [
  { marker: '[IMAGE_1]', url: source.image_url_1 },
  { marker: '[IMAGE_2]', url: source.image_url_2 },
  { marker: '[IMAGE_3]', url: source.image_url_3 },
];

for (const image of imageSpecs) {
  if (!image.url || !image.url.startsWith('https://')) {
    throw new Error(`找不到 ${image.marker} 對應的 HTTPS 圖片網址`);
  }
}

// Google Docs GET 回傳中，body.content 是一系列段落／結構區塊；
// 每個 paragraph.elements 的 textRun.content 可能包含 marker。
function findMarkerStartIndex(marker) {
  const contentBlocks = googleDoc.body?.content ?? [];

  for (const block of contentBlocks) {
    const elements = block.paragraph?.elements ?? [];

    for (const element of elements) {
      const text = element.textRun?.content ?? '';
      const offset = text.indexOf(marker);

      if (offset !== -1) {
        return element.startIndex + offset;
      }
    }
  }

  throw new Error(`Google Docs 中找不到 ${marker}；請確認文章寫入時保留了 marker。`);
}

const markerPositions = imageSpecs.map((image) => ({
  ...image,
  startIndex: findMarkerStartIndex(image.marker),
}));

// 一律從文件後方處理到前方，避免後面的刪除／插入改變前面 marker 的 index。
markerPositions.sort((a, b) => b.startIndex - a.startIndex);

const requests = [];
for (const image of markerPositions) {
  requests.push(
    {
      deleteContentRange: {
        range: {
          startIndex: image.startIndex,
          // 只刪除 [IMAGE_X] 本身，保留其後的換行，讓圖片獨立成段。
          endIndex: image.startIndex + image.marker.length,
        },
      },
    },
    {
      insertInlineImage: {
        uri: image.url,
        location: {
          index: image.startIndex,
        },
        objectSize: {
          width: {
            magnitude: 400,
            unit: 'PT',
          },
        },
      },
    },
  );
}

return [
  {
    json: {
      documentId: googleDoc.documentId,
      markerPositions: markerPositions.map(({ marker, startIndex }) => ({ marker, startIndex })),
      // 保留成字串，HTTP Request 的完整 JSON Body expression 可直接使用。
      batchUpdateBody: JSON.stringify({ requests }),
    },
  },
];

// 本次文件的預期 marker 位置示例為：
// [IMAGE_3] → 745、[IMAGE_2] → 512、[IMAGE_1] → 211。
// 每次產生新文章時，程式會重新讀取 Google Docs API 回傳內容，自動得到新的位置。

function getArticleText(nodeName) {
  const data = $(nodeName).first().json;

  return (
    data.output?.[0]?.content?.find(item => item.type === 'output_text')?.text ??
    data.output?.[0]?.content?.[0]?.text ??
    data.output_text ??
    data.text ??
    ''
  ).trim();
}

const part1 = getArticleText('Message a model');
const part2 = getArticleText('Write article part 2');

if (!part1 || !part2) {
  throw new Error('找不到文章前半部或後半部內容');
}

const article = `${part1}\n\n${part2}`;
const chineseCharacterCount = (article.match(/[\u4e00-\u9fff]/g) || []).length;

return [
  {
    json: {
      article,
      chineseCharacterCount,
    },
  },
];
